    enonce: "بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x - 2</span> حيث <span dir=\"ltr\" class=\"expr\">A = -7 - (x - 3) - [1 - (y + 3)]</span>",
    correction: [{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 3) = -x + 3</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [1 - (y + 3)] = -1 + y + 3</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -7 - x + 3 - 1 + y + 3</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-7 + 3 - 1 + 3)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-7 + 3 - 1 + 3 = -2</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - 2</span>"}],
