    correction: [{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(a - 2) - (b + 3) = (a - b) - 5</span>"},{"quoi":"نترجم الفرضية","math":"<span dir=\"ltr\" class=\"expr\">a - b &lt; 0</span>"},{"quoi":"إشارة الثابت","math":"<span dir=\"ltr\" class=\"expr\">-5 &lt; 0</span>"},{"quoi":"القاعدة","math":"مجموع عددين سالبين هو عدد سالب"},{"quoi":"إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">(a - b) - 5 &lt; 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a - 2 &lt; b + 3</span>"}],
